# 🔹 Correct Stack Implementation in C
Here’s a **fixed, clean version** of your code:

```c
#include <stdio.h>
#include <stdlib.h>

#define MAXSIZE 20

int stack[MAXSIZE]; // stack as global array

// PUSH function
void push(int *top, int item) {
    if (*top == MAXSIZE - 1) {
        printf("Stack Overflow!\n");
        return;
    }
    stack[++(*top)] = item;
    printf("%d pushed into stack\n", item);
}

// POP function
int pop(int *top) {
    if (*top == -1) {
        return -1; // underflow
    }
    return stack[(*top)--];
}

// DISPLAY function
void display(int top) {
    if (top == -1) {
        printf("Stack is Empty\n");
        return;
    }
    printf("Stack elements: ");
    for (int i = top; i >= 0; i--) {
        printf("%d ", stack[i]);
    }
    printf("\n");
}

// MAIN
int main() {
    int top = -1;
    int ch, item, p;

    while (1) {
        printf("\n1. Push\n2. Pop\n3. Display\n4. Exit\n");
        printf("Enter choice: ");
        scanf("%d", &ch);

        switch (ch) {
            case 1:
                printf("Enter element to push: ");
                scanf("%d", &item);
                push(&top, item);
                break;

            case 2:
                p = pop(&top);
                if (p == -1)
                    printf("Stack Underflow!\n");
                else
                    printf("Element popped: %d\n", p);
                break;

            case 3:
                display(top);
                break;

            case 4:
                exit(0);

            default:
                printf("Invalid Choice!\n");
        }
    }
    return 0;
}
```

