Now let’s move from **array-based stack** to **linked list stack**.  

This removes the fixed-size limit (`MAXSIZE`), since linked lists grow/shrink dynamically.  

---

# 🔹 How Stack Works with Linked List
- Instead of using an array, we use a **linked list** where the **head node is treated as the top** of the stack.  
- **PUSH** → Insert a new node at the beginning (head).  
- **POP** → Remove the node from the beginning (head).  
- **PEEK** → Return the head’s data.  

---

# 🔹 Linked List Stack Implementation in C

```c
#include <stdio.h>
#include <stdlib.h>

// Node structure
struct Node {
    int data;
    struct Node* next;
};

// PUSH operation
void push(struct Node** top, int item) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    if (!newNode) {
        printf("Stack Overflow (Heap memory full)\n");
        return;
    }
    newNode->data = item;
    newNode->next = *top;  // link new node to old top
    *top = newNode;        // update top
    printf("%d pushed into stack\n", item);
}

// POP operation
int pop(struct Node** top) {
    if (*top == NULL) {
        return -1; // stack underflow
    }
    struct Node* temp = *top;
    int popped = temp->data;
    *top = (*top)->next;   // move top down
    free(temp);            // free old top
    return popped;
}

// DISPLAY operation
void display(struct Node* top) {
    if (top == NULL) {
        printf("Stack is Empty\n");
        return;
    }
    printf("Stack elements: ");
    while (top != NULL) {
        printf("%d ", top->data);
        top = top->next;
    }
    printf("\n");
}

// MAIN
int main() {
    struct Node* top = NULL; // initially empty stack
    int ch, item, p;

    while (1) {
        printf("\n1. Push\n2. Pop\n3. Display\n4. Exit\n");
        printf("Enter choice: ");
        scanf("%d", &ch);

        switch (ch) {
            case 1:
                printf("Enter element to push: ");
                scanf("%d", &item);
                push(&top, item);
                break;

            case 2:
                p = pop(&top);
                if (p == -1)
                    printf("Stack Underflow!\n");
                else
                    printf("Element popped: %d\n", p);
                break;

            case 3:
                display(top);
                break;

            case 4:
                exit(0);

            default:
                printf("Invalid Choice!\n");
        }
    }
    return 0;
}
```

